typedef long long ll;

const ll INF = 1e16 + 239;
const int MAXN = 1e6 + 239;

ll a[MAXN];

namespace SegmentTree {
	int n;
	ll t[4 * MAXN];
	ll mod[4 * MAXN];

	void pull(int v) {
		t[v] = min(t[2 * v + 1], t[2 * v + 2]);
	}

	void apply(int v, ll val) {
		t[v] += val;
		mod[v] += val;
	}

	void push(int v) {
		if (mod[v] != 0) {
			apply(2 * v + 1, mod[v]);
			apply(2 * v + 2, mod[v]);
			mod[v] = 0;
		}
	}

	void build(int v, int l, int r) {
		if (l + 1 == r) {
			t[v] = a[l];
		} else {
			int m = (r + l) >> 1;
			build(2 * v + 1, l, m);
			build(2 * v + 2, m, r);
			pull(v);
		}
	}

	void add(int v, int l, int r, int ql, int qr, ll val) {
		if (r <= ql || qr <= l) {
			return;
		} else if (ql <= l && r <= qr) {
			apply(v, val);
		} else {
			push(v);
			int m = (r + l) >> 1;
			add(2 * v + 1, l, m, ql, qr, val);
			add(2 * v + 2, m, r, ql, qr, val);
			pull(v);
		}
	}

	int go_down(int v, int l, int r) {
		if (l + 1 == r) {
			return l;
		} else {
			push(v);
			int m = (r + l) >> 1;
			int res = -1;
			if (t[2 * v + 2] == 0) {
				res = go_down(2 * v + 2, m, r);
			} else {
				res = go_down(2 * v + 1, l, m);
			}
			pull(v);
			return res;
		}
	}

	void init(int n_) {
		n = n_;
		build(0, 0, n);
	}

	void add(int l, int r, ll val) {
		add(0, 0, n, l, r, val);
	}

	void add(int pos, ll val) {
		add(0, 0, n, pos, pos + 1, val);
	}

	int last_zero() {
		return go_down(0, 0, n);
	}
}

